        "caption": "Table 2.8—Screening for and diagnosis of GDM One-step strategy Perform a 75-g OGTT, with plasma glucose measurement when an individual is fasting and at 1 and 2 h, at 24–28 weeks of gestation in individuals not previously diagnosed with diabetes. The OGTT should be performed in the morning after an overnight fast of at least 8 h. The diagnosis of GDM is made when any of the following plasma glucose values are met or exceeded: • Fasting: 92 mg/dL (5.1 mmol/L) • 1 h: 180 mg/dL (10.0 mmol/L) • 2 h: 153 mg/dL (8.5 mmol/L) Two-step strategy Step 1: Perform a 50-g GLT (nonfasting), with plasma glucose measurement at 1 h, at 24–28 weeks of gestation in individuals not previously diagnosed with diabetes. If the plasma glucose level measured 1 h after the load is ≥130, 135, or 140 mg/dL (7.2,"
