          "2008;93:4774 – 4779 Diabet Med 2013;30:46 – 55 disease in the Diabetes Prevention Program",
          "2006;49:289 – 297 Open Diabetes Res Care 2017;5:e000438 Metab 2008;93:3936 – 3942",
