        "caption": "Table 9.3 and Table 9.4 for median monthly cost in the U.S. of noninsulin glu- cose-lowering agents and insulin, respec- tively. It is important to match complexity of the treatment plan to the self-manage- ment ability of older adults with diabetes and their available social and medical support. Many older adults with diabetes struggle to maintain the frequent blood glucose monitoring and insulin injection plans they previously followed, perhaps for many decades, as they develop medical conditions that may impair their ability to follow their treatment plan safely. Individu- alized glycemic goals should be established (Fig. 6.2 and Table 13.1) and periodically adjusted based on coexisting chronic ill- nesses, cognitive function, functional status, life expectancy, and risk of complications (2). Intensive glycemic management with medication plans including insulin and sul- fonylureas in older adults with complex medical conditions has been identified as overtreatment and found to be very com- mon in clinical practice (100–104) and may increase the risk of mortality (37). Ul- timately, the determination of whether a person is considered overtreated requires an elicitation of the person’s perceptions of the current medication burden and preferences for treatments. For those seeking to simplify their diabetes medica- tion plan, deintensification of plans in indi- viduals taking noninsulin glucose-lowering"
