        "id": "13.2",
        "page": 11,
        "caption": "Figure 13.2 provides a potential approach to simplification of insulin plans. Other Factors to Consider The needs of older adults with diabetes and their care partners should be evalu- ated to construct a tailored care plan. In- adequate social support and reduced access to long-term services and support may reduce these individuals’ quality of life and increase the risk of functional de- pendency (7). The living situation must be considered as it may affect diabetes management and support needs. Social and instrumental support networks (e.g., adult children and care partners) that pro- vide instrumental or emotional support for older adults with diabetes should be included in diabetes management discus- sions and shared decision-making. The need for ongoing support of older adults becomes even greater when transi- tions to acute care and long-term care (LTC) become necessary. Unfortunately, these transitions can lead to discontinuity in goals of care, errors in dosing, and changes in nutrition and activity (135). Older adults in assisted living facilities may not have support to administer their own medications, whereas those living in a nursing home for short-term rehabilitation or LTC may rely on first-line care partners including nursing and care professionals with variable clinical expertise. Those re- ceiving palliative care (with or without hospice) may require an approach that"
