        "caption": "Table 15.1—Checklist for preconception care for people with prediabetes, diabetes, or a history of gestational diabetes mellitus Preconception education should include: w Comprehensive nutrition assessment and recommendations for: • Overweight and obesity or underweight • Meal planning • Correction of dietary nutritional deficiencies • Caffeine intake • Safe food preparation technique w Lifestyle recommendations for: • Regular moderate exercise • Avoidance of hyperthermia (hot tubs) • Adequate sleep w Comprehensive diabetes self-management education w Counseling on diabetes in pregnancy per current standards, including natural history of insulin resistance in pregnancy and postpartum; preconception glycemic goals; avoidance of DKA and severe hyperglycemia; avoidance of severe hypoglycemia; progression of retinopathy in individuals with preexisting diabetes; PCOS (if applicable); fertility in people with diabetes; genetics of diabetes; risks to pregnancy including miscarriage, stillbirth, congenital malformations, macrosomia, preterm labor and delivery, hypertensive disorders in pregnancy w Supplementation • Folic acid supplement (400–800 mg/day routine) • Appropriate use of over-the-counter medications and supplements Health assessment and plan should include: w General evaluation of overall health w Evaluation of diabetes and its comorbidities and complications, including DKA and"
